            messaging = "Advocacy for universal healthcare and increased funding for hospitals and clinics."
        elif user_preferences.get('environment'):
            messaging = "Support for environmental protection and sustainable development."
        else:
            messaging = "Support for responsible governance and effective policy-making."

        # Return the campaign messaging as a JSON response
        return JsonResponse({'messaging': messaging})
